async function (variables) {
	var g = new ReadOnlyDetailView(variables.element);
	g.title = function (data) { return "" + kendo.htmlEncode(data.Number) + " [resource_shortdisplayname[from]]: " + kendo.htmlEncode(data.CreditorName) + " [resource_shortdisplayname[to]] " + kendo.htmlEncode(data.DebtorName) + ""; };
	// optional, but we want a subset of fields here so lets be explicit.
	g.fields = [
		{ field: "Number", title: "[resource_shortdisplayname[Number]]", description: "[resource_description[Number]]" },
		{ field: "DebtorName", title: "[resource_shortdisplayname[DebtorName]]", description: "[resource_description[DebtorName]]" },
		{ field: "DebtorState", template: function (data) { return "" + kendo.htmlEncode(B2B.transactionStates[data.DebtorState]) + ""; }, title: "[resource_shortdisplayname[DebtorState]]", description: "[resource_description[DebtorState]]" },
		{ field: "CreditorName", title: "[resource_shortdisplayname[CreditorName]]", description: "[resource_description[CreditorName]]" },
		{ field: "CreditorState", template: function (data) { return "" + (B2B.transactionStates[data.CreditorState.replaceAll(' ', '') || 'None']) + ""; }, title: "[resource_displayname[creditorstate]]", description: "[resource_description[creditorstate]]" },
		{ field: "FunderState", template: function (data) { return "" + ((data.FunderState) ? B2B.transactionStates[data.FunderState]: '') + ""; }, title: "[resource_shortdisplayname[FunderState]]", description: "[resource_description[FunderState]]" },
		{ field: "CreationDate", type: "date", format: type.dateFormat, title: "[resource_shortdisplayname[CreationDate]]", description: "[resource_description[CreationDate]]" },
		{ field: "ExpiryDate", type: "date", format: type.dateFormat + " HH:mm", title: "[resource_shortdisplayname[ExpiryDate]]", description: "[resource_description[ExpiryDate]]" },
		{ field: "DueDate", type: "date", format: type.dateFormat, title: "[resource_shortdisplayname[FunderPaymentDate]]", description: "[resource_description[FunderPaymentDate]]" },
		{ field: "DebtorPaymentDate", type: "date", format: type.dateFormat, title: "[resource_shortdisplayname[BuyerPaymentDate]]", description: "[resource_description[BuyerPaymentDate]]" },
		{ field: "LastUpdated", type: "date", format: type.dateFormat, title: "[resource_shortdisplayname[LastUpdated]]", description: "[resource_description[LastUpdated]]" },
		{ field: "Value", type: "number", format: type.moneyFormat, title: "[resource_shortdisplayname[Value]]", description: "[resource_description[Value]]"},
		{ field: "Rate", type: "number", format: type.moneyFormat, title: "[resource_shortdisplayname[rate]]", description: "[resource_description[rate]]"},
		{ field: "Cost", type: "number", format: type.moneyFormat, title: "[resource_shortdisplayname[cost]]", description: "[resource_description[cost]]"},
		{ field: "DaysEarly", title: "[resource_shortdisplayname[discountdays]]", template: function (data) { return "" + (Math.ceil(Math.abs(new Date(data.DebtorPaymentDate) - new Date(data.DueDate)) / (1000 * 60 * 60 * 24))) + ""; }}
	];
	g.splits = ["CreationDate"];
	g.toolbar = "";
	if(variables.backButton) {
		g.toolbar += "<button onClick='javascript: history.go(-1)'><span class='k-icon k-i-arrow-parent'></span> [resource_shortdisplayname[back]]</button>";
	}
	g.toolbar += "<button name=viewFundingDetails>[resource_displayname[fundingdetails]]</button>";

	variables.OfferDetails = g;
	return g;
}
